import{R as e,e as i,f as a,U as o}from"./chunks/framework.ywem4qy5.js";const g=JSON.parse('{"title":"Mailchimp","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/mailchimp.md","filePath":"integrations/email-marketing/mailchimp.md","lastUpdated":1775908585000}'),n={name:"integrations/email-marketing/mailchimp.md"};function r(l,t,s,h,c,p){return i(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="mailchimp" tabindex="-1">Mailchimp <a class="header-anchor" href="#mailchimp" aria-label="Permalink to &quot;Mailchimp&quot;">​</a></h1><p>Follow the below steps to connect to the Mailchimp API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Mailchimp as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-mailchimp-api" tabindex="-1">Step 2. Connect to the Mailchimp API <a class="header-anchor" href="#step-2-connect-to-the-mailchimp-api" aria-label="Permalink to &quot;Step 2. Connect to the Mailchimp API&quot;">​</a></h3><ol><li>Go to <a href="http://mailchimp.com/" target="_blank">Mailchimp</a> and login to your account.</li><li>Click on your profile dropdown on the top-right of the screen, and select <strong>Account</strong>.</li><li>Click on <strong>Extras</strong> → <strong>API keys</strong>.</li><li>Under the <strong>Your API keys</strong> section, click the <strong>Create A Key</strong> button.</li><li>Copy the newly created key into the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h3 id="additional-features" tabindex="-1">Additional Features <a class="header-anchor" href="#additional-features" aria-label="Permalink to &quot;Additional Features&quot;">​</a></h3><ul><li>Supports <a href="https://mailchimp.com/help/about-double-opt-in/" target="_blank" rel="noreferrer">Double Opt-in</a>.</li><li>Supports <a href="https://mailchimp.com/help/manage-tags/" target="_blank" rel="noreferrer">Tags</a>.</li><li>Supports <a href="https://mailchimp.com/help/getting-started-with-groups/" target="_blank" rel="noreferrer">Groups</a>.</li><li>Supports <a href="https://mailchimp.com/help/collect-consent-with-gdpr-forms/" target="_blank" rel="noreferrer">GDPR Fields</a>.</li></ul>',12)])])}const d=e(n,[["render",r]]);export{g as __pageData,d as default};
